from typing import TypedDict, Optional

class RowProxy:
    id: str
    first_name: str
    last_name: str

class User(TypedDict):
    id: str
    firstName: str
    lastName: str
    password: str

    @classmethod
    def from_row(cls, row: RowProxy) -> Optional["User"]:
        if not row:
            return None
        return User(id=row.id, firstName=row.first_name, lastName=row.last_name)
EOF
